    }, 15000);
    pendingMap.set(cmdId, {
      resolve: (ackPayload) => {
        clearTimeout(timeoutTimer);
        // cleanup fica; será limpo em 15s ou na próxima iteração
        resolve(ackPayload);
      },
      reject,
      ts: issuedAt,
    });
