  const mqttPayload = {
    cmd_id: cmdId, protocol_version: 1,
    cmd: body.cmd, params: body.params || {},
    issued_at: issuedAt.toISOString(), expires_at: expiresAt.toISOString(),
    origin: 'manual_app_remote', user_id: msg.user.id
