  for (const m of msgs) node.send(m);
} catch(e) { node.error('burst sweeper: ' + e.message); }
return null;

// E062_TEMP_HISTORY_v1 — historico de temperatura via Influx.
// Query params: from (ISO), to (ISO, default=NOW), every ('30s','1m','5m','1h', default='1m')
const pool = global.get('pgPool');
const queryApi = global.get('influxQuery');
if (!pool) { msg.statusCode=503; msg.payload={error:'db not ready'}; return msg; }
if (!queryApi) { msg.statusCode=503; msg.payload={error:'influx not ready'}; return msg; }

const id = msg.req.params.id;
const romId = (msg.req.params.romId || '').toUpperCase();
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ROM_RE = /^[0-9A-F]{16}$/;
if (!UUID_RE.test(id)) { msg.statusCode=400; msg.payload={error:'id invalido'}; return msg; }
if (!ROM_RE.test(romId)) { msg.statusCode=400; msg.payload={error:'romId invalido'}; return msg; }

const q = msg.req.query || {};
const from = (typeof q.from === 'string' && q.from) ? q.from : null;
const to = (typeof q.to === 'string' && q.to) ? q.to : null;
const every = (typeof q.every === 'string' && /^[0-9]+(s|m|h)$/.test(q.every)) ? q.every : '1m';
if (!from) { msg.statusCode=400; msg.payload={error:'from (ISO) obrigatorio'}; return msg; }
const fromMs = Date.parse(from);
if (!Number.isFinite(fromMs)) { msg.statusCode=400; msg.payload={error:'from invalido'}; return msg; }
const toMs = to ? Date.parse(to) : Date.now();
if (to && !Number.isFinite(toMs)) { msg.statusCode=400; msg.payload={error:'to invalido'}; return msg; }
if (toMs <= fromMs) { msg.statusCode=400; msg.payload={error:'to deve ser > from'}; return msg; }
// Limita janela: 90 dias maximo (retention do bucket)
if (toMs - fromMs > 90*24*3600*1000) { msg.statusCode=400; msg.payload={error:'janela maior que 90 dias'}; return msg; }

try {
  // Acesso: dispositivos_visiveis (owner ou share ativo).
  const isAdmin = msg.user && msg.user.role === 'admin';
  let devCheck;
  if (isAdmin) {
    devCheck = await pool.query('SELECT id FROM devices WHERE id=$1 LIMIT 1', [id]);
  } else {
    devCheck = await pool.query(
      'SELECT id FROM dispositivos_visiveis WHERE id=$1 AND viewer_id=$2 LIMIT 1',
      [id, msg.user.id]
    );
  }
  if (devCheck.rowCount === 0) { msg.statusCode=403; msg.payload={error:'sem acesso'}; return msg; }

  // Verifica que o sensor pertence a esse device (defensive).
  const senCheck = await pool.query(
    'SELECT nome, role FROM irrigation_temperature_sensors WHERE device_id=$1 AND rom_id=$2 LIMIT 1',
    [id, romId]
  );
  if (senCheck.rowCount === 0) { msg.statusCode=404; msg.payload={error:'sensor nao encontrado neste dispositivo'}; return msg; }

  const bucket = env.get('INFLUX_BUCKET') || 'telemetry';
  const fromIso = new Date(fromMs).toISOString();
  const toIso = new Date(toMs).toISOString();
  // Flux: filtra measurement temperature, tags device_id+rom_id, agrega mean.
  // Como tags podem conter caracteres especiais, faz sanitize bem-conservador.
  const sanitize = (s) => String(s).replace(/["\\]/g, '');
  const fluxQuery = `from(bucket: "${sanitize(bucket)}")
  |> range(start: ${fromIso}, stop: ${toIso})
  |> filter(fn: (r) => r._measurement == "temperature")
  |> filter(fn: (r) => r.device_id == "${sanitize(id)}")
  |> filter(fn: (r) => r.rom_id == "${sanitize(romId)}")
  |> filter(fn: (r) => r._field == "temperature_c")
  |> aggregateWindow(every: ${every}, fn: mean, createEmpty: false)
  |> yield(name: "mean")`;

  const points = [];
  await new Promise((resolve, reject) => {
    queryApi.queryRows(fluxQuery, {
      next(row, tableMeta) {
        const o = tableMeta.toObject(row);
        if (typeof o._value === 'number') {
          points.push({ ts: o._time, value: Number(o._value.toFixed(3)) });
        }
      },
      error(e) { reject(e); },
      complete() { resolve(); }
    });
  });

  msg.statusCode = 200;
  msg.payload = {
    sensor: { rom_id: romId, nome: senCheck.rows[0].nome, role: senCheck.rows[0].role },
    range: { from: fromIso, to: toIso, every },
    points
  };
} catch(e) {
  node.error('temp history: ' + e.message, msg);
  msg.statusCode = 500; msg.payload = { error: 'internal' };
}
return msg;

const auth = (msg.req.headers['authorization']||'').trim();
const m = auth.match(/^Bearer (.+)$/);
if (!m) { msg.statusCode=401; msg.payload={error:'missing bearer token'}; return [null, msg]; }
try {
  const secret = env.get('JWT_SECRET');
  const decoded = jwt.verify(m[1], secret);
  if (decoded.typ === 'refresh') { msg.statusCode=401; msg.payload={error:'refresh token cannot be used here'}; return [null, msg]; }
  msg.user = { id: decoded.sub, email: decoded.email, role: decoded.role };
  return [msg, null];
} catch(e) {
  msg.statusCode=401; msg.payload={error:'invalid token'}; return [null, msg];
}

// Reutiliza padrão de autenticação dos endpoints IRR-V1 (fnAuthIrrComandos)
const token = msg.req.headers['authorization']?.replace('Bearer ', '');
if (!token) { msg.statusCode = 401; msg.payload = { error: 'sem_token' }; node.send([null, msg]); return; }

let claims;
try {
  const jose = global.get('jose') || require('jose');
  const secret = new TextEncoder().encode(env.get('JWT_SECRET'));
  const { payload } = await jose.jwtVerify(token, secret);
  claims = payload;
} catch (e) {
  msg.statusCode = 401; msg.payload = { error: 'token_invalido' }; node.send([null, msg]); return;
}

msg._userId   = claims.sub;
msg._userRole = claims.role;
node.send([msg, null]);

const pg   = global.get('pgPool');
const mq   = global.get('mqttBroker');   // broker MQTT interno (registro via _e22)

const deviceId = msg.req.params.deviceId;
const { step, alarm_id } = msg.req.body || {};
const userId   = msg._userId;

// Validações de entrada
if (!deviceId || !alarm_id || ![1, 2].includes(Number(step))) {
  msg.statusCode = 400;
  msg.payload = { error: 'parametros_invalidos', detalhe: 'step (1|2) e alarm_id obrigatórios' };
  node.send(msg); return;
}

// ── Buscar alarme + serial do device ──────────────────────────────────────────
let alarmRow, deviceSerial;
try {
  const res = await pg.query(
    `SELECT a.id, a.device_id, a.tipo, a.severity, a.message, a.since,
             a.acked_at, a.acked_by_user_id, a.resolved_at, a.payload_json,
             d.serial
       FROM irrigation_alarms a
       JOIN devices d ON d.id = a.device_id
      WHERE a.id = $1 AND a.device_id = $2`,
    [alarm_id, deviceId]
  );
  if (res.rowCount === 0) {
    msg.statusCode = 404; msg.payload = { error: 'alarme_nao_encontrado' };
    node.send(msg); return;
  }
  alarmRow    = res.rows[0];
  deviceSerial = res.rows[0].serial;
} catch (e) {
  node.error('[fnIrrAlarmAck] pg query alarm: ' + e.message, msg);
  msg.statusCode = 500; msg.payload = { error: 'erro_banco' };
  node.send(msg); return;
}

if (alarmRow.resolved_at) {
  msg.statusCode = 409; msg.payload = { error: 'alarme_ja_resolvido' };
  node.send(msg); return;
}

const topic = `devices/${deviceSerial}/alarm/active`;
let newAckState;

if (Number(step) === 1) {
  // ── ACK step 1: confirmar visualização ────────────────────────────────────
  // Se já foi acked_once mas o frontend está refazendo step=1 (reset por timeout),
  // reverte para 'open' se acked_at < 31s atrás (dentro da janela de timeout do frontend)
  const jaNulo = !alarmRow.acked_at;
  const dentroJanela = alarmRow.acked_at &&
    (Date.now() - new Date(alarmRow.acked_at).getTime()) > 29_500;

  if (!jaNulo && !dentroJanela) {
    // Já ackado recentemente, idempotente
    newAckState = 'acknowledged_once';
  } else if (dentroJanela) {
    // Reset por timeout do frontend
    newAckState = 'open';
    await pg.query(
      'UPDATE irrigation_alarms SET acked_at = NULL, acked_by_user_id = NULL WHERE id = $1',
      [alarm_id]
    );
  } else {
    newAckState = 'acknowledged_once';
    await pg.query(
      'UPDATE irrigation_alarms SET acked_at = NOW(), acked_by_user_id = $2 WHERE id = $1',
      [alarm_id, userId]
    );
  }

} else {
  // ── ACK step 2: confirmar definitivamente ──────────────────────────────────
  if (!alarmRow.acked_at) {
    msg.statusCode = 422;
    msg.payload = { error: 'ack_step1_pendente', detalhe: 'Execute step=1 primeiro' };
    node.send(msg); return;
  }
  newAckState = 'acknowledged_final';
  await pg.query(
    'UPDATE irrigation_alarms SET resolved_at = NOW() WHERE id = $1',
    [alarm_id]
  );
}

// ── Publicar retained MQTT atualizado ─────────────────────────────────────────
const retainedPayload = JSON.stringify({
  kind:      alarmRow.tipo,
  severity:  alarmRow.severity || 'critico',
  message:   alarmRow.message,
  since:     alarmRow.since,
  ack_state: newAckState,
  alarm_id:  alarm_id,
});

try {
  // Usa o helper global mqttPublish injetado por _e22 ou similar
  // Fallback: tenta global 'mqttPublish'; se não existir, usa o broker direto
  const pub = global.get('mqttPublish');
  if (typeof pub === 'function') {
    await pub(topic, retainedPayload, { retain: true, qos: 1 });
  } else if (mq && typeof mq.publish === 'function') {
    await new Promise((res, rej) => mq.publish(topic, retainedPayload, { retain: true, qos: 1 }, (e) => e ? rej(e) : res()));
  } else {
    node.warn('[fnIrrAlarmAck] mqttPublish/mqttBroker não disponível no contexto global — retained NÃO publicado');
  }
} catch (mqErr) {
  node.error('[fnIrrAlarmAck] mqtt publish error: ' + mqErr.message, msg);
  // Não retorna erro 500 — banco já foi atualizado; frontend vai sincronizar pelo próximo poll
}

msg.statusCode = 200;
msg.payload = { ok: true, alarm_id, ack_state: newAckState };
node.send(msg);

// E055_ALARM_PUB_v1 — recovery de alarmes retidos no boot
// Roda 2s após deploy via injAlarmRecovery (once:true).
// Republica retained devices/<serial>/alarm/active para todos alarmes sem ack/resolve.
// Garante que clientes conectados antes do restart recebem o estado atual.
const pool = global.get('pgPool');
if (!pool) {
  node.warn('E055 recovery: pgPool não pronto, retry em 3s');
  setTimeout(async () => {
    const p2 = global.get('pgPool');
    if (!p2) { node.warn('E055 recovery: pgPool ainda ausente, desistindo'); return; }
    await runRecovery(p2);
  }, 3000);
  return;
}
await runRecovery(pool);

async function runRecovery(pool) {
  function sevOf(tipo) {
    return ['temperature_high','pump_runtime_exceeded','communication_lost'].includes(tipo)
      ? 'critico' : 'aviso';
  }
  try {
    // DISTINCT ON: um alarme por device (o de maior prioridade)
    const r = await pool.query(
      `SELECT DISTINCT ON (d.id)
              d.device_id AS serial,
              ia.id, ia.tipo, ia.message, ia.triggered_at
         FROM irrigation_alarms ia
         JOIN devices d ON d.id = ia.device_id
        WHERE ia.acked_at IS NULL AND ia.resolved_at IS NULL
        ORDER BY d.id,
                 CASE ia.tipo
                   WHEN 'temperature_high'      THEN 1
                   WHEN 'pump_runtime_exceeded' THEN 2
                   WHEN 'communication_lost'    THEN 3
                   WHEN 'sensor_missing'        THEN 4
                   ELSE 5 END,
                 ia.triggered_at ASC`
    );
    node.log('E055 recovery: ' + r.rowCount + ' alarme(s) ativo(s) a republicar');
    for (const row of r.rows) {
      node.send({
        topic:   'devices/' + row.serial + '/alarm/active',
        payload: JSON.stringify({
          kind:      row.tipo,
          severity:  sevOf(row.tipo),
          message:   row.message,
          since:     new Date(row.triggered_at).toISOString(),
          ack_state: 'open',
          alarm_id:  row.id,
        }),
        qos: 1, retain: true,
      });
    }
  } catch(e) {
    node.error('E055 recovery query: ' + e.message);
  }
}

// Marca ack_status='expired' em comandos pendentes que passaram do TTL.
const pool = global.get('pgPool');
if (!pool) return null;
try {
  const r = await pool.query(
    `UPDATE irrigation_command_log
        SET ack_status = 'expired',
            ack_received_at = NOW(),
            ack_reason = 'ttl_exceeded_no_ack'
      WHERE ack_status IS NULL
        AND expires_at < NOW()`
  );
  if (r.rowCount > 0) {
    node.warn('cmd_log expired sweeper: ' + r.rowCount + ' cmds marcados');
    node.status({fill:'yellow', shape:'dot', text: r.rowCount + ' expired ' + new Date().toISOString().slice(11,19)});
  } else {
    node.status({fill:'green', shape:'ring', text: 'ok ' + new Date().toISOString().slice(11,19)});
  }
} catch (e) {
  node.error('cmd_log sweeper: ' + e.message);
}
return null;
